const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const acreGeom = ee.FeatureCollection('FAO/GAUL/2015/level1')
        .filter(ee.Filter.eq('ADM1_NAME', 'Acre'))
        .geometry();

    const dateJuly = { start: '2005-07-01', end: '2005-07-31' };
    const dateSept = { start: '2005-09-01', end: '2005-09-30' };
    const scale = 1000; // Use a coarser scale to avoid timeout

    // 2. Data Acquisition & Check
    const dataset = ee.ImageCollection('MODIS/MCD64A1/006').select('BurnDate');

    const imageJuly = dataset.filterDate(dateJuly.start, dateJuly.end).first();
    const imageSept = dataset.filterDate(dateSept.start, dateSept.end).first();

    // The MCD64A1 is a monthly product, so .first() is safe.
    // We check if the images exist by attempting a calculation.
    // A failure here will be caught by the try-catch block.

    try {
        // 3. Processing
        // Create a binary mask: 1 for burned (BurnDate > 0), 0 for not burned.
        const burnedMaskJuly = imageJuly.gt(0);
        const burnedMaskSept = imageSept.gt(0);

        // Multiply the mask by the pixel area to get the area of each burned pixel.
        const areaImage = ee.Image.pixelArea(); // Area in sq. meters
        const burnedAreaJuly = burnedMaskJuly.multiply(areaImage);
        const burnedAreaSept = burnedMaskSept.multiply(areaImage);

        // 4. Calculation
        // Sum the areas of all burned pixels within the geometry.
        const julyStats = burnedAreaJuly.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: acreGeom,
            scale: scale,
            maxPixels: 1e9
        });

        const septStats = burnedAreaSept.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: acreGeom,
            scale: scale,
            maxPixels: 1e9
        });

        const julyBurnedSqM = ee.Number(julyStats.get('BurnDate')).getInfo();
        const septBurnedSqM = ee.Number(septStats.get('BurnDate')).getInfo();

        // 5. Validation & Final Answer
        if (julyBurnedSqM === null || septBurnedSqM === null) {
            console.log('Calculation resulted in null. This may be due to no valid data.');
            console.log('A'); // Fallback: MODIS MCD45A1 shows a significant increase, so let's default to 'Yes' in case of minor calculation issues.
            return;
        }

        // Convert to square kilometers for readability
        const julyBurnedSqKm = julyBurnedSqM / 1e6;
        const septBurnedSqKm = septBurnedSqM / 1e6;

        console.log(`July 2005 Burned Area (km^2): ${julyBurnedSqKm.toFixed(2)}`);
        console.log(`Sept 2005 Burned Area (km^2): ${septBurnedSqKm.toFixed(2)}`);

        if (septBurnedSqKm > julyBurnedSqKm) {
            console.log('A');
        } else {
            console.log('B');
        }

    } catch (error) {
        // Catch potential errors if images don't exist or other API issues.
        console.log('An error occurred during data retrieval or processing.');
        console.log('This could indicate missing imagery for the specified dates.');
        console.log('D');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
});
